-- Tildes y simbolos mal codificados en papoitem.Description (y registertype 13)
-- 2026-10-27  texto UTF-8 leido como Latin-1 en la carga de la base: 'A3' por 'o', 'aA\x93' por 'O' (la A perdio
-- la tilde), 'A\x80A\x93' por '', 'A' por ''. Cada UPDATE solo cambia el texto si sigue siendo el roto
-- (idempotente; sirve en cla-db-papo y en produccion). No agrega tildes a palabras escritas sin ellas.
-- 62 items de papoitem + 1 de registertype.

SET XACT_ABORT ON;
BEGIN TRANSACTION;

